def lead_pwm3(m=192, K=24, N=20):
    tot = (K + m) * P
    t = np.arange(tot) / P
    w = 0.5 - 0.34 * (0.5 - 0.5 * np.cos(2 * np.pi * t / m))
    x = pulse_bl(t, w, N)
    env = 0.72 + 0.28 * np.exp(-t / 6.0)
    env[K * P:] = 0.72 + 0.28 * np.exp(-K / 6.0)
    return to16(x * env, 0.88), K * P, m * P
